**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("uczniowie.txt");
    string nazwisko, miasto;
    int wynik;
    map<string, int> ile;
    map<string, int> suma;

    while (plik >> nazwisko >> miasto >> wynik) {
        ile[miasto]++;
        suma[miasto] += wynik;
    }

    // a)
    cout << "a) Uczniow z miasta:" << endl;
    string maxMiasto; int maxIle = 0;
    for (auto &p : ile) {
        cout << "   " << p.first << ": " << p.second << endl;
        if (p.second > maxIle) { maxIle = p.second; maxMiasto = p.first; }
    }

    // b)
    cout << endl << "b) Srednie wyniki:" << endl;
    cout << fixed << setprecision(2);
    string bestSrMiasto; double bestSr = 0;
    for (auto &p : ile) {
        double sr = (double)suma[p.first] / p.second;
        cout << "   " << p.first << ": " << sr << endl;
        if (sr > bestSr) { bestSr = sr; bestSrMiasto = p.first; }
    }

    // c) i d)
    cout << endl << "c) Najwiecej uczniow: " << maxMiasto << " (" << maxIle << ")" << endl;
    cout << "d) Najwyzsza srednia: " << bestSrMiasto << " (" << bestSr << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Dwie mapy: `ile` zlicza uczniow per miasto, `suma` gromadzi sumy wynikow. Po wczytaniu iterujemy po mapach, aby obliczyc srednie i znalezc ekstrema. `map` sortuje klucze alfabetycznie.

Weryfikacja:
- Gdansk: 3 uczniow, suma 67+91+82=240, srednia 240/3=80.00
- Krakow: 3 uczniow, suma 85+73+64=222, srednia 222/3=74.00
- Warszawa: 4 uczniow, suma 78+92+88+55=313, srednia 313/4=78.25
- Najwiecej: Warszawa (4)
- Najwyzsza srednia: Gdansk (80.00)
